def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j]==0 or seen[i][j]: continue
            comp=[]; dq=deque([(i,j)]); seen[i][j]=True
            while dq:
                y,x=dq.popleft(); comp.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and grid[ny][nx]!=0:
                        seen[ny][nx]=True; dq.append((ny,nx))
            cs=set(comp)
            # BFS assigning layer = number of color changes from outside
            layer={}; dq=deque()
            for (y,x) in comp:
                if any((y+dy,x+dx) not in cs for dy,dx in((1,0),(-1,0),(0,1),(0,-1))) or y in(0,h-1) or x in(0,w-1):
                    if (y,x) not in layer:
                        layer[(y,x)]=0; dq.append((y,x))
            while dq:
                y,x=dq.popleft()
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if p in cs and p not in layer:
                        layer[p]=layer[(y,x)]+(1 if grid[p]!=grid[(y,x)] else 0)
                        dq.append(p)
            laycol={}
            for (y,x) in comp: laycol.setdefault(layer[(y,x)],grid[y][x])
            md=max(laycol); seq=[laycol[d] for d in range(md+1)]; rev=seq[::-1]
            for (y,x) in comp: out[y][x]=rev[layer[(y,x)]]
    return out

